`timescale 1ns/1ps
module tb_sample_ntt_parser;reg clk=0,rst_n=0,start=0,iv=0,ordy=1;reg[23:0]id;wire busy,done,error,ir,ov;wire[11:0]oc;wire[7:0]oi;wire[1:0]dom;wire[31:0]groups,acc,rej;integer fd,rc,v,n,g,i,got,checks=0;reg[23:0]words[0:511];reg[11:0]exp[0:255];string file;always#5 clk=~clk;sample_ntt_parser dut(clk,rst_n,start,busy,done,error,iv,ir,id,ov,ordy,oc,oi,dom,groups,acc,rej);
 initial begin if(!$value$plusargs("VECTOR_FILE=%s",file))$fatal(1,"VECTOR_FILE");fd=$fopen(file,"r");repeat(3)@(negedge clk);rst_n=1;for(v=0;v<8;v=v+1)begin rc=$fscanf(fd,"%d\n",n);for(g=0;g<n;g=g+1)rc=$fscanf(fd,"%h\n",words[g]);for(i=0;i<256;i=i+1)rc=$fscanf(fd,"%h\n",exp[i]);@(negedge clk);start=1;@(negedge clk);start=0;got=0;for(g=0;g<n;g=g+1)begin while(!ir)@(negedge clk);iv=1;id=words[g];@(negedge clk);iv=0;end while(!done)@(negedge clk);if(error||got!=256||groups!=n)$fatal(1,"status v=%0d groups=%0d/%0d",v,groups,n);end $display("PASS tb_sample_ntt_parser vectors=8 coeff_checks=%0d",checks);$finish;end
 always@(posedge clk)if(ov&&ordy)begin if(oi!==got[7:0]||oc!==exp[got]||oc>=3329||dom!=2'b10)$fatal(1,"v=%0d i=%0d exp=%0d got=%0d",v,got,exp[got],oc);got=got+1;checks=checks+1;end endmodule
